using Test, GravitationalWaveforms, StaticArrays, LinearAlgebra, DelimitedFiles, Random

# SEOBNRv5PHM time-domain waveform (milestone P3) against pyseobnr 0.3.7's SEOBNRv5PHM_opt (anti-symmetric modes on,
# polarizations from the co-precessing modes, 0.1 M sampling; reference data in test/data/phm_wf, generated by
# scripts/pyseobnr_phm_wf_reference.py --antisym --test): q1.5_a, q8_d (retrograde remnant, af < 0), q3_fref
# (f_ref > f_start). Compared at pyseobnr's samples in dynamics time (model.t - model.t[0]). pyseobnr's ODE at
# rtol = atol = 1e-11 (converged; its production 1e-8 moves t_attach by up to 0.3 M and the merger-ringdown overlaps
# to ~1e-3, see seobnrv5phm_dyn_tests.jl). Worst measured: t_attach 0.010 M, 1 - overlap of h+ - i hx 1.1e-6 (merger-
# ringdown) / 1.1e-8 (inspiral), co-precessing modes 4.4e-7, anti-symmetric modes 5e-5 (merger-ringdown, q8_d).

const _PHMW = GravitationalWaveforms
const _PHM_WF_DIR = joinpath(@__DIR__, "data", "phm_wf")

function _phmw_header(f)
    d = Dict{String,Any}()
    for m in eachmatch(r"(\w+)=(\[[^\]]*\]|[-0-9.eE+]+)", readline(f))
        d[m[1]] = m[2][1] == '[' ? parse.(Float64, split(m[2][2:end-1], ",")) : parse(Float64, m[2])
    end
    return d
end
_phmw_rows(f) = readdlm(f, ',', Float64; comments = true)
_phmw_ov(a, b) = abs(sum(conj.(a) .* b)) / sqrt(sum(abs2, a) * sum(abs2, b))

@testset "SEOBNRv5PHM waveform vs pyseobnr ($tag)" for tag in ("q1.5_a", "q8_d", "q3_fref")
    pre = joinpath(_PHM_WF_DIR, "pyseobnr037_phmwf_as_$(tag)")
    h = _phmw_header(pre * "_info.csv")
    info = vec(_phmw_rows(pre * "_info.csv"))
    wf = _phmw_rows(pre * "_wf.csv")
    S = _PHMW._seobv5phm_build(h["m1"], h["m2"], h["chi1"], h["chi2"], h["omega_ref"], h["omega_start"])

    # attachment, remnant, frame at the attachment
    @test abs(S.t_a - info[1]) < 0.03
    @test abs(S.t_peak - (-info[16])) < 0.03
    @test abs(S.Mf / info[4] - 1) < 1e-6
    @test abs(S.af - info[5]) < 1e-5
    @test S.sgn_af == Int(info[6])
    al_a, be_a, _ = _PHMW._qangles(S.frame_a.q)      # the attachment frame is stored as a quaternion
    @test abs(be_a - info[8]) < 1e-4
    @test abs(rem2pi(al_a - info[7], RoundNearest)) < 1e-3
    @test norm(S.Jhat - info[10:12]) < 1e-4
    @test norm(S.Lhat_a - info[13:15]) < 1e-4
    # anti-symmetric fits
    A = S.asym
    @test all(A.flags)
    @test abs(A.habs22 / info[18] - 1) < 5e-5
    @test maximum(abs.(collect(A.om_fit) .- info[19:21]) ./ info[19:21]) < 1e-3

    ts = wf[:, 1]
    insp = ts .< S.t_a - 50
    mr = .!insp
    for k in 1:6
        ref = complex.(wf[:, 4+2(k-1)], wf[:, 5+2(k-1)])
        us = [_PHMW._seobv5phm_coprec(S, k, t) for t in ts]
        @test _phmw_ov(ref[insp], us[insp]) > 1 - 2e-6
        @test _phmw_ov(ref[mr], us[mr]) > 1 - 2e-6
    end
    for j in 1:3
        ref = complex.(wf[:, 16+2(j-1)], wf[:, 17+2(j-1)])
        us = [_PHMW._seobv5phm_asym(S, j, t) for t in ts]
        @test _phmw_ov(ref[insp], us[insp]) > 1 - 4e-6
        @test _phmw_ov(ref[mr], us[mr]) > 1 - 1.5e-4
    end
    hpc_ref = complex.(wf[:, 2], wf[:, 3])
    hpc = [_PHMW._seobv5phm_hpc(S, t, h["inclination"], h["phiref"]) for t in ts]
    @test _phmw_ov(hpc_ref[insp], hpc[insp]) > 1 - 1e-7
    @test _phmw_ov(hpc_ref[mr], hpc[mr]) > 1 - 5e-6
end

@testset "SEOBNRv5PHM quaternion helpers" begin
    for (al, be, ga) in ((0.3, 1.1, -2.0), (-2.5, 0.2, 0.7), (1.0, 2.9, 3.0))
        q = _PHMW._qeuler(al, be, ga)
        a2, b2, g2 = _PHMW._qangles(q)
        @test abs(rem2pi(a2 - al, RoundNearest)) < 1e-12
        @test abs(b2 - be) < 1e-12
        @test abs(rem2pi(g2 - ga, RoundNearest)) < 1e-12
        # rotation of z by the quaternion = (sin b cos a, sin b sin a, cos b)
        z = _PHMW._qmul(_PHMW._qmul(q, (0.0, 0.0, 0.0, 1.0)), _PHMW._qconj(q))
        @test maximum(abs.((z[2] - sin(be) * cos(al), z[3] - sin(be) * sin(al), z[4] - cos(be)))) < 1e-12
    end
    # from_rotation_matrix round trip
    e1, e2, e3 = _PHMW._seobv5phm_jframe(normalize(SVector(0.3, -0.5, 0.8)))
    q = _PHMW._qfrom_rotmat(e1, e2, e3)
    for (e, ax) in ((e1, (0.0, 1.0, 0.0, 0.0)), (e3, (0.0, 0.0, 0.0, 1.0)))
        v = _PHMW._qmul(_PHMW._qmul(q, ax), _PHMW._qconj(q))
        @test norm(SVector(v[2], v[3], v[4]) - e) < 1e-12
    end
end

# The device sample reverse's pieces (GravitationalWaveBayes `SEOBNRPHMSampleRev.jl`): `_seobv5phm_hpc` split at t_attach into
# `_hpc_insp` / `_hpc_mr`, and the anti-symmetric build's de-duplicated triad projections (`_asym_b1_a`, `_asym_mr_a`)
# against the per-call helpers (the split shares the interpolation / rotation / NQC basis: equal to rounding).
@testset "SEOBNRv5PHM hpc split + asym build de-duplication" begin
    for (m1, c1, c2) in ((0.6, [0.3, 0.1, 0.2], [0.1, -0.2, 0.3]), (0.8, [0.5, -0.3, 0.1], [0.2, 0.6, -0.4]))
        S = _PHMW._seobv5phm_build(m1, 1 - m1, c1, c2, 0.018, 0.017)
        incl, phr = 0.7, 0.4
        t_end = S.t_a + _PHMW._EOBIMR_NTAU * S.mr[1].tau
        for tq in range(0.0, t_end; length = 401)
            h = _PHMW._seobv5phm_hpc(S, tq, incl, phr)
            hs = tq <= S.t_a ? _PHMW._seobv5phm_hpc_insp(S, tq, incl, phr) : _PHMW._seobv5phm_hpc_mr(S, tq, incl, phr)
            @test abs(hs - h) <= 1e-13 * abs(h)
        end
        A = S.asym; t_a = S.t_a; he = 0.05
        sts = _PHMW._seobv5phm_attach_states(S.dyn, S.b, t_a)
        P = -(_PHMW._seobv5phm_asym_p1(_PHMW._seobv5phm_sts_at(sts, he / 0.5)) -
              _PHMW._seobv5phm_asym_p1(_PHMW._seobv5phm_sts_at(sts, -he / 0.5))) / (2he)
        A0 = (flags = A.flags, b6 = A.b6, b1 = (0.0, 0.0, 0.0))
        @test all(isapprox.(A.b1, ntuple(j -> _PHMW._seobv5phm_asym_b1(S, A0, j, sts, he, A.om_fit, P), 3); rtol = 1e-12))
        # the quartic through the attachment states reproduces them at the nodes
        @test all(_PHMW._seobv5phm_sts_at(sts, i - 3.0) == sts[i] for i in 1:5)
    end
end

@testset "SEOBNRv5PHM observer rotation: Cayley-Klein mode factors = -2Y_lm(beta, alpha) e^{2i gamma}" begin
    rng = Xoshiro(21)
    worst = 0.0
    for t in 1:2000
        al, ga = 2pi * rand(rng), 2pi * rand(rng)
        be = t == 1 ? 0.0 : t == 2 ? Float64(pi) : pi * rand(rng)
        q = _PHMW._qeuler(al, be, ga)
        for k in 1:6
            yp, ym = _PHMW._seobv5phm_swsh_q(k, _PHMW._qcayley(q)...)
            rp, rm = _PHMW._seobv5phm_swsh(k, be, al) .* cis(2ga)
            worst = max(worst, abs(yp - rp), abs(ym - rm))
            # q and -q are the same rotation
            yn = _PHMW._seobv5phm_swsh_q(k, _PHMW._qcayley(.-q)...)
            worst = max(worst, abs(yn[1] - yp), abs(yn[2] - ym))
        end
    end
    @test worst < 1e-13
end
